  }

  auto engine_vector_data =
      ProximaEngineHelper::convert_to_engine_vector(vector_data, is_sparse_);
  if (0 != index->add(engine_vector_data.value(), doc_id)) {
    return Status::InternalError("Failed to add vector to index");
  }
  return Status::OK();
}

